gin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">You paid {{ order.paid_amount | money }} for this order. We will contact you about the refund.</p>{% endif %}⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Questions? Reply to this email{% if shop.phone %} or call us at {{ shop.phone }}{% endif %}.</p>⏎</td></tr>⏎⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Order</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.name }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Items</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.item_count }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Total</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.total_price | money }}</td></tr>⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">To pay on delivery</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.cod_amount | money }}</td></tr>{% endif %}⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-25T05:37:40.845Z', '2026-10-25T05:37:42.823Z', 'Order cancelled', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('21371d48-c0a0-4a93-95b8-afcb82b56dd3', 'ORDER_RETURNED', 'EMAIL', 0, 'Return received for order {{ order.name }}', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="en">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>We received your return</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}Order {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">We received your return</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Hi {{ customer.first_name | default: "there" }}, the returned parcel for order {{ order.name }} has reached us.</p>⏎{% if order.paid_amount > 0 %}<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">We will contact you about your payment of {{ order.paid_amount | money }}.</p>{% endif %}⏎</td></tr>⏎⏎⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-25T05:37:40.845Z', '2026-10-25T05:37:42.823Z', 'Returned', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('729a7f21-5ed0-4244-92f3-574523d864f2', 'DELIVERY_FAILED', 'SMS', 0, NULL, 'The courier could not reach you with order {{order_number}}. Please call {{store_phone}} to get it delivered. - {{store_name}}', '2026-10-25T05:37:42.823Z', '2026-10-25T05:37:42.823Z', 'Courier could not reach', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('5dd3084c-4bee-4979-9742-b87d1c23a85d', 'DELIVERY_FAILED', 'WHATSAPP', 0, NULL, replace('Hi {{customer_first_name}}, the courier could not reach you with your order {{order_number}}. Please call us at {{store_phone}} or reply here so we can send it again.⏎⏎The {{store_name}} team', '⏎', char(10)), '2026-10-25T05:37:42.823Z', '2026-10-25T05:37:42.823Z', 'Courier could not reach', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('a70eaff7-6831-42a5-afe1-8da9e0eb3328', 'DELIVERY_FAILED', 'EMAIL', 0, 'We could not deliver order {{ order.name }}', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="en">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>The courier could not reach you</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}Order {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">The courier could not reach you</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Hi {{ customer.first_name | default: "there" }}, the courier tried to deliver your order {{ order.name }} but could not reach you.</p>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">To get it delivered, {% if shop.phone %}call us at {{ shop.phone }} or {% endif %}reply to this email.</p>⏎</td></tr>⏎{% if shipment.tracking_url or order.status_url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ shipment.tracking_url | default: order.status_url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">Track your parcel</a>⏎</td></tr>{% endif %}⏎⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-25T05:37:42.823Z', '2026-10-25T05:37:42.823Z', 'Courier could not reach', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
